function removeDuplicados(valores) {
  const resultados = [];
  for (let i = 0; i < valores.length; i++) {
    if (!resultados.find((j) => j === valores[i])) {
      resultados.push(valores[i]);
    }
  }
  return resultados;
}

console.assert(JSON.stringify(removeDuplicados(['ana', 'bia', 'ana', 'caio', 'bia']) === JSON.stringify(['ana', 'bia', 'caio'])), 'Faltou verificar se a string original era única');
console.assert(JSON.stringify(removeDuplicados([]) === []), 'Faltou verificar se a string original era vazio');
console.assert(JSON.stringify(removeDuplicados(['x']) === ['x']), 'Faltou verificar se a string original era única')
